     *     maxRetries?: int|null,
     * } $args
     * @return array{
     *     days: int,
     *     timezone: string,
     *     totals: array{
     *         cards: array{now: int, prev: int},
     *         customers: array{now: int, prev: int},
     *         visits: array{now: int, prev: int},
     *         redeems: array{now: int, prev: int},
     *     },
     *     series: list<array{
     *         day: string,
     *         cards: int,
     *         customers: int,
     *         visits: int,
     *         redeems: int,
     *     }>,
     *     feed: list<array{
     *         at: string,
     *         kind: 'join'|'earn'|'redeem'|'spend'|'load'|'accrue',
     *         name: string|null,
     *         delta: int|float|null,
     *         unit: string|null,
     *         location: string|null,
     *         program: string|null,
     *     }>,
     *     branches: list<array{id: string, name: string, cards: int, visits: int, redeems: int}>|null,
     *     joinUrl: string|null,
     * }
     *
     * @throws RewloyException
     */
