     *     visitWindowHours: int,
     * }
     *
     * @throws RewloyException
     */
    public function getAnalytics(array $args = []): array
    {
        /**
         * @var array{
         *     days: int,
         *     kpis: array{
         *         activeCards: int,
         *         newCards: int,
         *         visits: int,
         *         visitors: int,
         *         returningVisitors: int,
         *         redeems: int,
         *     },
         *     daily: list<array{day: string, visits: int}>,
         *     weekly: list<array{week: string, newVisitors: int, returning: int}>,
         *     funnel: list<array{
         *         programId: string,
         *         name: string,
         *         issued: int,
         *         used: int,
         *         rewarded: int,
         *     }>,
         *     branches: list<array{
         *         locationId: string,
