         *         visits: int,
         *         visitors: int,
         *         newCards: int,
         *     }>,
         *     topCustomers: list<array{personId: string, name: string, visits: int, lastVisit: string}>,
         *     wallet: array{inAppleWallet: int, holdingRelevance: int},
         *     visitWindowHours: int,
         * } $data
         */
        $data = $this->call('getAnalytics', $args);
        return $data;
    }

    /**
     * İşlem kaydı: kasa
     *
     * Kartlarda yapılan her işlem, yeniden eskiye: damga, puan, ödül, harcama, yükleme, ziyaret, kupon kullanımı… kim (ekip üyesi, API anahtarı ya da sistem), nerede, hangi kart. `day` işletmenin takvim günüdür. Planda `auditlog` özelliği gerekir. `limit` en fazla 200. `at` Rewloy'nun kaydı yazdığı andır (sıra da ona göredir); sonradan yazılan bir satışın olduğu an `occurredAt`'tadır. Bir geri alma `kind: "adjust"` olarak görünür (kuponun ya da indirim kartının geri verilen kullanımı: `delta: 1`, `unit: null`). Kapsamı programlarla sınırlı bir kimlik (ör. mağaza eklentisinin anahtarı) yalnız kendi programlarının kartlarını görür. Bir mağaza eklentisinin anahtarına kişisel veri gelmez: ekip üyesi `actor` yerine "ekip üyesi" yazar, `personId` null'dır.
     *
     * **Kimlik:** API anahtarı, ekip oturumu.
     *
     * **Yetki:** `analytics.read` — Analitik görüntüleme.
     *
     * `GET /v1/activity`
     *
     * Arguments:
     * - `query.locationId`: Tek bir şube (kapsamınız içinde)
     * - `query.seatId`: Yalnız bu ekip üyesinin yaptıkları
     * - `query.day`: YYYY-AA-GG
     * - `query.programId`: Tek bir program (kapsamınız içinde). Kapsamı programlarla sınırlı bir kimlik (ör. mağaza eklentisinin anahtarı) yalnız kendi programlarını görür; programsız istekte de yalnız onlar sayılır.
     * - `query.serial`: Kart numarası ya da başı
     * - `merchant`: Ekip oturumu birden fazla işletmede koltuk taşıyorsa hangi işletme için olduğu (tek işletmede gerekmez). The `Rewloy-Merchant` header; the client's `merchant` by default.
     *
     * @see https://rewloy.com/gelistiriciler/api#op-listActivity API referansı
     *
     * @param array{
     *     query?: array{
     *         locationId?: string|null,
     *         seatId?: string|null,
     *         day?: string|null,
     *         kind?: 'earn'|'redeem'|'spend'|'load'|'accrue'|'visit'|'use'|'issue'|'adjust'|'expire'|'hold'|'release'|'refund'|null,
     *         programId?: string|null,
     *         serial?: string|null,
     *         page?: int|null,
     *         limit?: int|null,
     *     },
     *     merchant?: string|null,
     *     timeout?: int|float|null,
     *     maxRetries?: int|null,
     * } $args
     * @return array{
     *     data: list<array{
     *         at: string,
     *         kind: string,
     *         delta: int|float|null,
     *         unit: string|null,
     *         currency: string|null,
     *         serial: string,
     *         personId: string|null,
     *         program: string,
     *         location: string|null,
     *         actor: string,
