     * @see https://rewloy.com/gelistiriciler/api#op-holderRecoveryStatus API referansı
     *
     * @param array{
     *     body: array{token: string},
     *     timeout?: int|float|null,
     *     maxRetries?: int|null,
     * } $args
     * @return array{
     *     number: string,
     *     state: 'review'|'refused'|'pending_wait'|'approved'|'applied'|'cancelled',
     *     kind: 'email'|'phone',
     *     from: string,
     *     to: string,
     *     createdAt: string,
     *     dueAt: string|null,
     *     message: string|null,
     *     messageAt: string|null,
     *     decidedBy: 'auto'|'support',
     *     cancelledBy: 'owner'|'link'|'support'|'system'|null,
     *     supportUrl: string,
     * }
     *
     * @throws RewloyException
     */
    public function holderRecoveryStatus(array $args): array
    {
        /**
         * @var array{
         *     number: string,
         *     state: 'review'|'refused'|'pending_wait'|'approved'|'applied'|'cancelled',
         *     kind: 'email'|'phone',
         *     from: string,
         *     to: string,
         *     createdAt: string,
         *     dueAt: string|null,
         *     message: string|null,
         *     messageAt: string|null,
         *     decidedBy: 'auto'|'support',
         *     cancelledBy: 'owner'|'link'|'support'|'system'|null,
         *     supportUrl: string,
         * } $data
         */
        $data = $this->call('holderRecoveryStatus', $args);
        return $data;
    }
}
